using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed retrieval: returns JsonTypeInfo<Person> directly.
JsonTypeInfo<Person> personInfo = (JsonTypeInfo<Person>)options.GetTypeInfo(typeof(Person));
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");

// Serialize using the typed metadata
var json = JsonSerializer.Serialize(new Person("Alice", 30), personInfo);
Console.WriteLine($"Serialized: {json}");

// 2) Probe without throwing: TryGetTypeInfo returns false if unavailable.
bool found = options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info);
Console.WriteLine($"\nTryGetTypeInfo(Person) => found={found}, type={info?.Type.Name}");

// Probe for a type NOT in the resolver (UnknownWidget has no metadata)
bool foundUnknown = options.TryGetTypeInfo(typeof(UnknownWidget), out JsonTypeInfo? unknownInfo);
Console.WriteLine($"TryGetTypeInfo(UnknownWidget) => found={foundUnknown}, info is null={unknownInfo is null}");

// Records used in the demo
public record Person(string Name, int Age);
public class UnknownWidget { } // will be resolvable via reflection-based resolver too

