using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Options with the default (reflection-based) resolver
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// ──────────────────────────────────────────────────────
// 1) Strongly-typed retrieval — returns JsonTypeInfo<T>
// ──────────────────────────────────────────────────────
JsonTypeInfo<Person> personInfo = (JsonTypeInfo<Person>)options.GetTypeInfo(typeof(Person));
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");

var json = JsonSerializer.Serialize(new Person("Alice", 30), personInfo);
Console.WriteLine($"Serialized: {json}");

// ──────────────────────────────────────────────────────
// 2) Probe without throwing — TryGetTypeInfo
// ──────────────────────────────────────────────────────

// Case A: type IS resolvable
if (options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info))
{
    Console.WriteLine($"\nTryGet(Person): success — {info!.Type.Name}");
}

// Case B: use a resolver that only handles Person, so Widget is NOT resolvable
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = new LimitedResolver()
};

if (limited.TryGetTypeInfo(typeof(Widget), out _))
    Console.WriteLine("TryGet(Widget): found (unexpected)");
else
    Console.WriteLine("TryGet(Widget): not found — no exception thrown ✓");

// ── Types ────────────────────────────────────────────
public record Person(string Name, int Age);
public class Widget { public int Id { get; set; } }

// A resolver that only knows about Person
file class LimitedResolver : IJsonTypeInfoResolver
{
    private readonly DefaultJsonTypeInfoResolver _inner = new();

    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options)
    {
        if (type == typeof(Person))
            return _inner.GetTypeInfo(type, options);
        return null; // unknown type
    }
}
